import * as Arr from 'effect/Array'
import * as Effect from 'effect/Effect'
import * as Layer from 'effect/Layer'
import * as Opt from 'effect/Option'
import * as Schema from 'effect/Schema'
// Generated by `bun run update-licenses`.
import licenses from './licenses.generated.json' with { type: 'json' }
import { type License, Licenses } from './licenses.ts'

/** What the About page shows of each package: the shape of `licenses.generated.json`, which the script writes with it. */
export const Entries = Schema.Record(
  Schema.String,
  Schema.Struct({
    licenses: Schema.optional(Schema.String),
    repository: Schema.optional(Schema.String),
    publisher: Schema.optional(Schema.String),
    email: Schema.optional(Schema.String),
    copyright: Schema.optional(Schema.String),
    name: Schema.optional(Schema.String),
    description: Schema.optional(Schema.String),
  }),
)

export const layer = Layer.succeed(Licenses, {
  // The file was written with `Entries`: one that does not decode is a bug of the build.
  all: Schema.decodeEffect(Entries)(licenses).pipe(
    Effect.orDie,
    Effect.map((entries) =>
      Arr.map(Object.entries(entries), ([packageName, entry]): License => ({
        packageName,
        licenses: Opt.fromNullishOr(entry.licenses),
        repository: Opt.fromNullishOr(entry.repository),
        publisher: Opt.fromNullishOr(entry.publisher),
        email: Opt.fromNullishOr(entry.email),
        copyright: Opt.fromNullishOr(entry.copyright),
        name: Opt.fromNullishOr(entry.name),
        description: Opt.fromNullishOr(entry.description),
      }))
    ),
  ),
})
